        format!(
            "cloned the work-repo, but its {} [repos].agent is missing, so no agent-repo \
             was cloned.\nAdd it, or rename repos.bot to repos.agent if the config is \
             pre-0.80.0.",
            crate::config_md::VC_CONFIG_MD
        )
