//! Shared test helpers for dual-repo integration tests.
//!
//! Provides a `Fixture` that wraps `crate::init::init`
//! plus a per-process unique-tempdir helper so parallel tests don't
//! collide. Lifted out of the `sync` test module (originally inline at
//! `sync.rs:521-560`) so `push`'s tests (0.37.0) and any future
//! subcommand's tests can sit on the same harness without
//! copy-paste drift.
//!
//! Test-only: the whole module is gated at its declaration site via
//! `#[cfg(test)] mod test_helpers;`.

use std::fs;
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicU64, Ordering};
use std::time::{SystemTime, UNIX_EPOCH};

use crate::common::write_file;
use crate::config::RepoSelector;
use crate::context::Context;
use crate::init::{InitArgs, InitParams, init};
use crate::options_flags::account::AccountOption;
use crate::options_flags::config::ConfigOption;
use crate::options_flags::por::PorFlag;
use crate::options_flags::provision_bundle::ProvisionOptionFlagBundle;
use crate::options_flags::repo::RepoOption;
use crate::options_flags::use_template::UseTemplateOption;
use crate::test_tmp_root::{resolve_tmp_root, should_keep_tempdir};

/// A named acceptance fixture under the workspace's `[test]
/// fixtures` directory, or `None` with a notice on stderr when it is
/// absent, so a bare clone's `cargo test` passes.
///
/// - The directory comes from this crate's own `.vc-config.md`,
///   resolved relative to the manifest dir, never from the current
///   directory, so the harness's cwd does not matter.
/// - A fixture is a dual workspace laid out as `vc-x1 clone` lays
///   one out, its README listing the relationships its tests assert
///   and `relationships.json` carrying them.
pub fn fixture(name: &str) -> Option<PathBuf> {
    let root = Path::new(env!("CARGO_MANIFEST_DIR"));
    let cfg = crate::config_md::load(root)
        .expect("load this crate's own config")
        .expect("this crate has a .vc-config.md");
    let Some(dir) = crate::toml_simple::toml_get(&cfg.map, "test.fixtures") else {
        eprintln!("fixture {name}: no [test] fixtures key in .vc-config.md: skipping");
        return None;
    };
    let path = crate::common::resolve_repo_path(root, dir).join(name);
    if path.join(".jj").is_dir() {
        Some(path)
    } else {
        eprintln!("fixture {name} absent at {}: skipping", path.display());
        None
    }
}

/// Per-process counter so same-nanosecond tempdir collisions yield
/// distinct paths when tests run in parallel.
static COUNTER: AtomicU64 = AtomicU64::new(0);

/// Fresh `Context` for op-level tests: default user config, no
/// sessions open, and no tty. Matches the production shape of one
/// `Context` per invocation without reading the developer's real
/// config or the terminal `cargo test` may have been run from.
pub fn test_ctx() -> Context {
    let mut ctx = Context::new(crate::config::UserConfig::default());
    ctx.stdin_is_tty = false;
    ctx
}

